import { deserializeBigIntsInObject } from "../numbers";
export async function fetchApiOrders(ctx, params) {
    const orders = await ctx.api.fetchJson("/v1/orders", {
        query: {
            address: params.address,
        },
    });
    return orders.map((o) => deserializeBigIntsInObject(o, { handleInts: true }));
}
